css:
:root {
  --riz-font: "Segoe UI", Arial, sans-serif;

  --riz-metal: #D7D8DB;
  --riz-outline: #4E4E4E;
  --riz-fiber: #0A638F;

  --riz-steam: #930606;
  --riz-condensate: #4E4E4E;
  --riz-control: #01524F;
  --riz-valve: #0E0E55;

  --riz-text: #000000;

  --riz-roller-width: 2.2px;
  --riz-fiber-width: 1.8px;
  --riz-process-width: 1.6px;
  --riz-control-width: 1.6px;
  --riz-valve-width: 1.4px;
}

/* Entorno */

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.rizado-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  font-family: var(--riz-font);
  pointer-events: none;
}

.rizado-svg {
  display: block;
  width: 100%;
  height: 100%;
  background: transparent;
  shape-rendering: geometricPrecision;
}

.rizado-widget,
.rizado-widget * {
  animation: none !important;
  transition: none !important;
}

/* Metal satinado */

.riz-metal-base {
  stop-color: var(--riz-metal);
}

.riz-metal-panel {
  fill: url("#riz-panel-metal");
  stroke: var(--riz-outline);
  stroke-width: 1.6px;
  stroke-linejoin: round;
}

.riz-metal-top {
  fill: url("#riz-top-metal");
  stroke: var(--riz-outline);
  stroke-width: 1.6px;
  stroke-linejoin: round;
}

.riz-metal-side {
  fill: url("#riz-side-metal");
  stroke: var(--riz-outline);
  stroke-width: 1.6px;
  stroke-linejoin: round;
}

.riz-equipment-shadow {
  filter: url("#riz-equipment-shadow");
}

.riz-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.7px;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.48;
}

.riz-edge-shade {
  fill: none;
  stroke: #555D69;
  stroke-width: 0.7px;
  opacity: 0.22;
}

/* Poleas: sin anillo interior */

.riz-roller {
  fill: url("#riz-roller-metal");
  stroke: var(--riz-outline);
  stroke-width: var(--riz-roller-width);
  filter: url("#riz-roller-shadow");
}

.riz-center-pin {
  fill: var(--riz-outline);
  stroke: #F0F1F3;
  stroke-width: 0.65px;
}

/* Cuerda */

.riz-fiber {
  fill: none;
  stroke: var(--riz-fiber);
  stroke-width: var(--riz-fiber-width);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.riz-fiber-ribbon {
  fill: none;
  stroke: var(--riz-fiber);
  stroke-width: 1.6px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Elementos mecánicos */

.riz-mechanical-line {
  fill: none;
  stroke: var(--riz-outline);
  stroke-width: 1.5px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.riz-mechanical-detail {
  fill: none;
  stroke: var(--riz-outline);
  stroke-width: 0.85px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.riz-belt {
  fill: none;
  stroke: var(--riz-outline);
  stroke-width: 1.6px;
  stroke-linejoin: round;
}

/* Tuberías */

.riz-steam,
.riz-condensate,
.riz-control {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.riz-steam {
  stroke: var(--riz-steam);
  stroke-width: var(--riz-process-width);
}

.riz-condensate {
  stroke: var(--riz-condensate);
  stroke-width: var(--riz-process-width);
}

.riz-control {
  stroke: var(--riz-control);
  stroke-width: var(--riz-control-width);
}

/* Los extremos no invaden el interior de las válvulas. */

.riz-valve-connection {
  stroke-linecap: butt;
}

/* Flechas */

.riz-steam-arrow {
  fill: var(--riz-steam);
  stroke: var(--riz-outline);
  stroke-width: 1.2px;
  stroke-linejoin: round;
}

.riz-return-arrow {
  fill: var(--riz-condensate);
  stroke: var(--riz-outline);
  stroke-width: 1.2px;
  stroke-linejoin: round;
}

/* Válvulas */

.riz-valve-body {
  fill: none;
  stroke: var(--riz-valve);
  stroke-width: var(--riz-valve-width);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.riz-valve-link {
  fill: none;
  stroke: var(--riz-valve);
  stroke-width: 0.7px;
  stroke-linecap: round;
}

.riz-valve-actuator {
  fill: var(--riz-valve);
  stroke: var(--riz-valve);
  stroke-width: 1px;
}

/* Gabinete */

.riz-cabinet-ventilation {
  fill: url("#riz-ventilation");
  stroke: none;
}

.riz-vent-dot {
  fill: var(--riz-outline);
  opacity: 0.22;
}

.riz-panel-recess {
  fill: #BEC1C7;
  stroke: var(--riz-outline);
  stroke-width: 1px;
}

.riz-panel-instrument {
  fill: #E8EAED;
  stroke: var(--riz-outline);
  stroke-width: 0.85px;
}

.riz-panel-mark {
  fill: var(--riz-outline);
  stroke: none;
}

.riz-inlet {
  fill: #7B7F87;
  stroke: var(--riz-outline);
  stroke-width: 1.1px;
  stroke-linejoin: round;
}

/* Texto */

.riz-footer {
  fill: var(--riz-text);
  font-family: var(--riz-font);
  font-size: 16px;
  font-style: italic;
  font-weight: 500;
  text-anchor: end;
}
